def minimumSwap(s1, s2):
    swaps_x_x = 0
    swaps_y_y = 0
    swaps_x_y = 0
    swaps_y_x = 0

    for c1, c2 in zip(s1, s2):
        if c1 == 'x' and c2 == 'x':
            swaps_x_x += 1
        elif c1 == 'y' and c2 == 'y':
            swaps_y_y += 1
        elif c1 == 'x' and c2 == 'y':
            swaps_x_y += 1
        elif c1 == 'y' and c2 == 'x':
            swaps_y_x += 1

    if (swaps_x_y + swaps_y_x) % 2 != 0:
        return -1

    return (swaps_x_x + swaps_y_y + abs(swaps_x_y - swaps_y_x)) // 2

